import sys

def main():
    data = sys.stdin.read().split()
    H = int(data[0]); W = int(data[1])
    grid = data[2:2+H]
    total = H * W

    is_magnet = bytearray(total)
    for i in range(H):
        row = grid[i]
        base = i * W
        for j in range(W):
            if row[j] == '#':
                is_magnet[base + j] = 1

    movable = bytearray(total)
    for i in range(H):
        base = i * W
        for j in range(W):
            idx = base + j
            if is_magnet[idx]:
                continue
            has_mag = False
            if i > 0 and is_magnet[idx - W]:
                has_mag = True
            elif i < H-1 and is_magnet[idx + W]:
                has_mag = True
            elif j > 0 and is_magnet[idx - 1]:
                has_mag = True
            elif j < W-1 and is_magnet[idx + 1]:
                has_mag = True
            if not has_mag:
                movable[idx] = 1

    parent = list(range(total))
    size = [1] * total

    def find(x):
        root = x
        while parent[root] != root:
            root = parent[root]
        while parent[x] != root:
            parent[x], x = root, parent[x]
        return root

    def union(a, b):
        ra, rb = find(a), find(b)
        if ra == rb:
            return
        if size[ra] < size[rb]:
            ra, rb = rb, ra
        parent[rb] = ra
        size[ra] += size[rb]

    for i in range(H):
        base = i * W
        for j in range(W):
            idx = base + j
            if not movable[idx]:
                continue
            if i + 1 < H:
                nidx = idx + W
                if movable[nidx]:
                    union(idx, nidx)
            if j + 1 < W:
                nidx = idx + 1
                if movable[nidx]:
                    union(idx, nidx)

    extra = {}
    for i in range(H):
        base = i * W
        for j in range(W):
            idx = base + j
            if is_magnet[idx] or movable[idx]:
                continue
            seen = set()
            if i > 0:
                nidx = idx - W
                if movable[nidx]:
                    seen.add(find(nidx))
            if i < H-1:
                nidx = idx + W
                if movable[nidx]:
                    seen.add(find(nidx))
            if j > 0:
                nidx = idx - 1
                if movable[nidx]:
                    seen.add(find(nidx))
            if j < W-1:
                nidx = idx + 1
                if movable[nidx]:
                    seen.add(find(nidx))
            for r in seen:
                extra[r] = extra.get(r, 0) + 1

    ans = 1
    for idx in range(total):
        if movable[idx] and parent[idx] == idx:
            val = size[idx] + extra.get(idx, 0)
            if val > ans:
                ans = val

    print(ans)

