def makeSmallestPalindrome(s: str) -> str:
    chars = list(s)
    left, right = 0, len(chars) - 1
    while left < right:
        if chars[left] != chars[right]:
            min_char = min(chars[left], chars[right])
            chars[left] = min_char
            chars[right] = min_char
        left += 1
        right -= 1
    return "".join(chars)
