import sys

def normalize(shape):
    min_r = min(r for r, c in shape)
    min_c = min(c for r, c in shape)
    return tuple(sorted((r - min_r, c - min_c) for r, c in shape))

def rotate(shape):
    # 90 degrees clockwise: (r, c) -> (c, -r)
    return tuple(sorted((c, -r) for r, c in shape))

def get_rotations(shape):
    seen = set()
    res = []
    cur = normalize(shape)
    for _ in range(4):
        if cur not in seen:
            seen.add(cur)
            res.append(cur)
        cur = normalize(rotate(cur))
    return res

def get_placements(shape):
    max_r = max(r for r, c in shape)
    max_c = max(c for r, c in shape)
    h = max_r + 1
    w = max_c + 1
    placements = []
    for dr in range(4 - h + 1):
        for dc in range(4 - w + 1):
            mask = 0
            for r, c in shape:
                rr = r + dr
                cc = c + dc
                mask |= 1 << (rr * 4 + cc)
            placements.append(mask)
    return placements

def solve():
