    if len(data) < 12:
        print("No")
        return

    grids = []
    for i in range(3):
        g = []
        for j in range(4):
            row = data[i * 4 + j]
            for k, ch in enumerate(row):
                if ch == '#':
                    g.append((j, k))
        grids.append(g)

    total_cells = sum(len(g) for g in grids)
    if total_cells != 16:
        print("No")
        return

    full_mask = (1 << 16) - 1
    placements = []
    for g in grids:
        masks = set()
        for rot in get_rotations(g):
            for mask in get_placements(rot):
                masks.add(mask)
        placements.append(list(masks))

    p0 = placements[0]
    p1 = placements[1]
    p2_set = set(placements[2])

    for m0 in p0:
        for m1 in p1:
            if m0 & m1:
                continue
            combined = m0 | m1
            needed = full_mask ^ combined
            if needed in p2_set:
                print("Yes")
                return

    print("No")

