import sys

def main():
    input_data = sys.stdin.read().split()
    idx = 0
    H = int(input_data[idx]); idx+=1
    W = int(input_data[idx]); idx+=1
    grid = []
    for i in range(H):
        grid.append(input_data[idx]); idx+=1

    MOD = 998244353
    N = H*W

    parent = list(range(N))
    rank_ = [0]*N

    def find(x):
        root = x
        while parent[root] != root:
            root = parent[root]
        while parent[x] != root:
            parent[x], x = root, parent[x]
        return root

    def union(x,y):
        rx, ry = find(x), find(y)
        if rx == ry:
            return
        if rank_[rx] < rank_[ry]:
            rx, ry = ry, rx
        parent[ry] = rx
        if rank_[rx] == rank_[ry]:
            rank_[rx] += 1

    def idx_of(i,j):
        return i*W + j

    # Union adjacent green cells
    for i in range(H):
        row = grid[i]
        for j in range(W):
            if row[j] == '#':
                cur = idx_of(i,j)
                if j+1 < W and grid[i][j+1] == '#':
                    union(cur, idx_of(i,j+1))
                if i+1 < H and grid[i+1][j] == '#':
                    union(cur, idx_of(i+1,j))

    # Count distinct components C
    roots_set = set()
    green_count = 0
    for i in range(H):
        row = grid[i]
        for j in range(W):
            if row[j] == '#':
                green_count += 1
                roots_set.add(find(idx_of(i,j)))
    C = len(roots_set)

    R = N - green_count  # number of red cells

    sumK = 0
    dr = [-1,1,0,0]
    dc = [0,0,-1,1]

    for i in range(H):
        row = grid[i]
        for j in range(W):
            if row[j] == '.':
                seen = []
                for k in range(4):
                    ni = i + dr[k]
                    nj = j + dc[k]
                    if 0 <= ni < H and 0 <= nj < W and grid[ni][nj] == '#':
                        r = find(idx_of(ni,nj))
                        found = False
                        for s in seen:
                            if s == r:
                                found = True
                                break
                        if not found:
                            seen.append(r)
                sumK += len(seen)

    # total sum of newComponents over all red cells = R*(C+1) - sumK
    total = (R * ((C+1) % MOD)) % MOD
    total = (total - sumK) % MOD
    total = (total + MOD) % MOD

    inv_R = pow(R, MOD-2, MOD)
    ans = (total * inv_R) % MOD

    print(ans)

