import sys

def main():
    input_data = sys.stdin.read().split()
    idx = 0
    N = int(input_data[idx]); idx+=1
    M = int(input_data[idx]); idx+=1

    INF = float('inf')
    dist = [[INF]*N for _ in range(N)]
    for i in range(N):
        dist[i][i] = 0

    for _ in range(M):
        u = int(input_data[idx]); idx+=1
        v = int(input_data[idx]); idx+=1
        w = int(input_data[idx]); idx+=1
        u -= 1
        v -= 1
        if w < dist[u][v]:
            dist[u][v] = w

    # Floyd Warshall
    for k in range(N):
        dk = dist[k]
        for i in range(N):
            dik = dist[i][k]
            if dik == INF:
                continue
            di = dist[i]
            for j in range(N):
                if dk[j] == INF:
                    continue
                nd = dik + dk[j]
                if nd < di[j]:
                    di[j] = nd

    full_mask = (1 << N) - 1

    # dp[mask][i] = min cost to have visited all vertices in mask, currently at vertex i
    size = 1 << N
    dp = [[INF]*N for _ in range(size)]

    for i in range(N):
        dp[1 << i][i] = 0

    for mask in range(1, size):
        dp_mask = dp[mask]
        for i in range(N):
            cur = dp_mask[i]
            if cur == INF:
                continue
            if not (mask & (1 << i)):
                continue
            dist_i = dist[i]
            for j in range(N):
                if mask & (1 << j):
                    continue
                dij = dist_i[j]
                if dij == INF:
                    continue
                new_mask = mask | (1 << j)
                nd = cur + dij
                if nd < dp[new_mask][j]:
                    dp[new_mask][j] = nd

    ans = INF
    dp_full = dp[full_mask]
    for i in range(N):
        if dp_full[i] < ans:
            ans = dp_full[i]

    if ans == INF:
        print("No")
    else:
        print(ans)

if __name__ == "__main__":
    main()
```

