from typing import List

def maxEnergy(energy: List[int], k: int) -> int:
    n = len(energy)
    acc = [0] * k
    max_total = float('-inf')
    for i in range(n - 1, -1, -1):
        r = i % k
        if i + k < n:
            acc[r] = energy[i] + acc[r]
        else:
            acc[r] = energy[i]
        if acc[r] > max_total:
            max_total = acc[r]
    return max_total
