        for k in range(1, n + 1):
            if n % k != 0:
                continue
            m = n // k
            max_sum = pref[k] - pref[0]
            min_sum = max_sum
            for b in range(1, m):
                s = pref[(b + 1) * k] - pref[b * k]
                if s > max_sum:
                    max_sum = s
                elif s < min_sum:
                    min_sum = s
            diff = max_sum - min_sum
            if diff > ans:
                ans = diff
