def beautifulNumbers(low: int, high: int, k: int) -> int:
    from functools import lru_cache

    def count(n: int) -> int:
        if n < 0:
            return 0
        s = str(n)
        length = len(s)

        @lru_cache(maxsize=None)
        def dp(pos, diff, mod, started, tight):
            if pos == length:
                return 1 if started and diff == 0 and mod == 0 else 0

            limit = int(s[pos]) if tight else 9
            res = 0
            for d in range(0, limit + 1):
                new_started = started or d > 0
                new_tight = tight and (d == limit)
                if not new_started:
                    # still leading zeros, digit not counted
                    res += dp(pos + 1, diff, mod, False, new_tight)
                else:
                    nd = diff + (1 if d % 2 == 0 else -1)
                    nmod = (mod * 10 + d) % k
                    res += dp(pos + 1, nd, nmod, True, new_tight)
            return res

        result = dp(0, 0, 0, False, True)
        dp.cache_clear()
        return result

    return count(high) - count(low - 1)
