import sys

def main():
    input_data = sys.stdin.read().split('\n')
    idx = 0
    H, W = map(int, input_data[idx].split())
    idx += 1
    grid = []
    for i in range(H):
        grid.append(input_data[idx])
        idx += 1

    start = None
    goal = None
    for i in range(H):
        for j in range(W):
            c = grid[i][j]
            if c == 'S':
                start = (i, j)
            elif c == 'T':
                goal = (i, j)

    N = int(input_data[idx])
    idx += 1

    medicine = {}
    for _ in range(N):
        parts = input_data[idx].split()
        idx += 1
        r, c, e = int(parts[0]), int(parts[1]), int(parts[2])
        medicine[(r-1, c-1)] = e

    NEG = -1
    best = [[NEG]*W for _ in range(H)]
    si, sj = start
    best[si][sj] = 0

    heap = [(0, si, sj)]  # store negative energy for max-heap simulation, but let's just use negative directly

    # We'll use a max-heap by pushing negative values
    heap = [(-0, si, sj)]

    def is_blocked(i, j):
        return grid[i][j] == '#'

    while heap:
        neg_energy, ci, cj = heapq.heappop(heap)
        energy = -neg_energy
        if energy < best[ci][cj]:
            continue

        eff = energy
        if (ci, cj) in medicine:
            if medicine[(ci, cj)] > eff:
                eff = medicine[(ci, cj)]

        if eff <= 0:
            continue

        new_e = eff - 1

        # neighbors
        for di, dj in [(-1,0),(1,0),(0,-1),(0,1)]:
            ni, nj = ci+di, cj+dj
            if 0 <= ni < H and 0 <= nj < W:
                if not is_blocked(ni, nj):
                    if new_e > best[ni][nj]:
                        best[ni][nj] = new_e
                        heapq.heappush(heap, (-new_e, ni, nj))

    gi, gj = goal
    if best[gi][gj] >= 0:
        print("Yes")
