def longestSpecialSubstring(s: str) -> int:
    n = len(s)
    # Build a list of maximal block lengths for each character
    blocks = [[] for _ in range(26)]
    i = 0
    while i < n:
        j = i
        while j < n and s[j] == s[i]:
            j += 1
        length = j - i
        blocks[ord(s[i]) - ord('a')].append(length)
        i = j

    # Try possible lengths from longest to shortest
    for L in range(n, 0, -1):
        for lst in blocks:
            total = 0
            for block_len in lst:
                if block_len >= L:
                    total += block_len - L + 1
                    if total >= 3:
                        return L
    return -1
