import sys

def main():
    data = sys.stdin.read().split()
    A = list(map(int, data))
    # A_flat[i] corresponds to cell index i = row*3+col (0-indexed)

    LINES = []
    # rows
    for r in range(3):
        LINES.append([r*3+0, r*3+1, r*3+2])
    # cols
    for c in range(3):
        LINES.append([0*3+c, 1*3+c, 2*3+c])
    # diagonals
    LINES.append([0,4,8])
    LINES.append([2,4,6])

    FULL = 0x1FF  # 9 bits all set

    def check_win(mask):
        for line in LINES:
            ok = True
            for idx in line:
                if not (mask & (1 << idx)):
                    ok = False
                    break
            if ok:
                return True
        return False

    memo = {}

    def solve(red, blue):
        key = (red, blue)
        if key in memo:
            return memo[key]

        total_moves = bin(red).count('1') + bin(blue).count('1')
        player = 0 if total_moves % 2 == 0 else 1  # 0 = Takahashi, 1 = Aoki

        white = (~(red | blue)) & FULL
        cells = [i for i in range(9) if white & (1 << i)]

        winner = None

        for c in cells:
            if player == 0:
                nr = red | (1 << c)
                nb = blue
            else:
                nr = red
                nb = blue | (1 << c)

            if player == 0 and check_win(nr):
                res = 0
            elif player == 1 and check_win(nb):
                res = 1
            else:
                if (nr | nb) == FULL:
                    score0 = 0
                    score1 = 0
                    for i in range(9):
                        if nr & (1 << i):
                            score0 += A[i]
                        elif nb & (1 << i):
                            score1 += A[i]
                    res = 0 if score0 > score1 else 1
                else:
                    res = solve(nr, nb)

            if res == player:
                winner = player
                break

        if winner is None:
            winner = 1 - player

        memo[key] = winner
        return winner

    result = solve(0, 0)
    if result == 0:
        print("Takahashi")
    else:
        print("Aoki")

if __name__ == "__main__":
    main()
