```python
def minChanges(s: str, k: int) -> int:
    n = len(s)
    INF = float('inf')

    # Precompute cost[l][r] = min changes to make s[l..r] a semi-palindrome
    cost = [[INF] * n for _ in range(n)]

    for l in range(n):
        for r in range(l, n):
            length = r - l + 1
            if length == 1:
                cost[l][r] = INF  # can't be semi-palindrome
                continue

            divisors = [d for d in range(1, length) if length % d == 0]
            best = INF
            for d in divisors:
                total = 0
                for start in range(d):
                    indices = list(range(l + start, r + 1, d))
                    m = len(indices)
                    for j in range(m // 2):
                        if s[indices[j]] != s[indices[m - 1 - j]]:
                            total += 1
                if total < best:
                    best = total
            cost[l][r] = best

    # DP
    dp = [[INF] * (k + 1) for _ in range(n + 1)]
    dp[0][0] = 0

    for i in range(1, n + 1):
        for j in range(1, k + 1):
            for m in range(j - 1, i):
                if dp[m][j - 1] != INF:
                    c = cost[m][i - 1]
                    if c != INF and dp[m][j - 1] + c < dp[i][j]:
                        dp[i][j] = dp[m][j - 1] + c

    return dp[n][k]
```

