import heapq

def minimizeStringValue(s: str) -> str:
    count = [0] * 26
    for ch in s:
        if ch != '?':
            count[ord(ch) - ord('a')] += 1

    heap = [(count[i], chr(ord('a') + i)) for i in range(26)]
    heapq.heapify(heap)

    result = list(s)
    for i, ch in enumerate(s):
        if ch == '?':
            cnt, letter = heapq.heappop(heap)
            result[i] = letter
            heapq.heappush(heap, (cnt + 1, letter))

