def getMaxFunctionValue(receiver, k):
    n = len(receiver)
    LOG = k.bit_length()
    if LOG == 0:
        LOG = 1

    up = [[0] * n for _ in range(LOG)]
    sm = [[0] * n for _ in range(LOG)]

    for i in range(n):
        up[0][i] = receiver[i]
        sm[0][i] = receiver[i]

    for j in range(1, LOG):
        for i in range(n):
            mid = up[j-1][i]
            up[j][i] = up[j-1][mid]
            sm[j][i] = sm[j-1][i] + sm[j-1][mid]

    ans = 0
    for x in range(n):
        cur = x
        total = x
        remaining = k
        for j in range(LOG):
            if remaining & (1 << j):
                total += sm[j][cur]
                cur = up[j][cur]
        if total > ans:
            ans = total

    return ans
