from typing import List

def incremovableSubarrays(nums: List[int]) -> int:
    n = len(nums)
    # left_ok[i] = True if nums[0..i] is strictly increasing
    left_ok = [False] * n
    for i in range(n):
        if i == 0:
            left_ok[i] = True
        else:
            left_ok[i] = left_ok[i-1] and nums[i-1] < nums[i]
    # right_ok[i] = True if nums[i..n-1] is strictly increasing
    right_ok = [False] * n
    for i in range(n-1, -1, -1):
        if i == n-1:
            right_ok[i] = True
        else:
            right_ok[i] = right_ok[i+1] and nums[i] < nums[i+1]
    ans = 0
    for l in range(n):
        for r in range(l, n):
            # check prefix part
            if l > 0 and not left_ok[l-1]:
                continue
            # check suffix part
            if r+1 < n and not right_ok[r+1]:
                continue
            # check boundary between prefix and suffix
            if l > 0 and r+1 < n and not (nums[l-1] < nums[r+1]):
                continue
            ans += 1
    return ans
