def shortestSuperstring(a: str, b: str, c: str) -> str:
    from itertools import permutations

    def merge_two(x: str, y: str) -> str:
        # Find max overlap between suffix of x and prefix of y
        max_len = min(len(x), len(y))
        for i in range(max_len, 0, -1):
            if x[-i:] == y[:i]:
                return x + y[i:]
        return x + y

    def merge_three(s1: str, s2: str, s3: str) -> str:
        merged = merge_two(s1, s2)
        merged = merge_two(merged, s3)
        return merged

    strings = [a, b, c]
    best = None

    for perm in permutations(strings):
        candidate = merge_three(perm[0], perm[1], perm[2])
        # Ensure all three original strings are substrings (should be true by construction)
        if a in candidate and b in candidate and c in candidate:
            if best is None:
                best = candidate
            else:
                if len(candidate) < len(best):
                    best = candidate
                elif len(candidate) == len(best) and candidate < best:
                    best = candidate

    return best
