def minOperationsToMedianK(nums, k):
    nums = sorted(nums)
    n = len(nums)
    mid = n // 2
    ops = 0
    if nums[mid] == k:
        return 0
    elif nums[mid] < k:
        i = mid
        while i < n and nums[i] < k:
            ops += k - nums[i]
            i += 1
    else:
        i = mid
        while i >= 0 and nums[i] > k:
            ops += nums[i] - k
            i -= 1
    return ops
