def numberOfStableArrays(zero: int, one: int, limit: int) -> int:
    MOD = 10**9 + 7

    # dp[z][o][last] = number of stable arrays using z zeros, o ones, ending with 'last'
    dp0 = [[0] * (one + 1) for _ in range(zero + 1)]  # ending with 0
    dp1 = [[0] * (one + 1) for _ in range(zero + 1)]  # ending with 1

    # Base cases: all zeros (no ones) or all ones (no zeros)
    for z in range(1, min(zero, limit) + 1):
        dp0[z][0] = 1
    for o in range(1, min(one, limit) + 1):
        dp1[0][o] = 1

    for z in range(0, zero + 1):
        for o in range(0, one + 1):
            if z == 0 and o == 0:
                continue
            # dp0[z][o]: last block is zeros, length k (1..min(limit,z))
            if z > 0:
                total = 0
                max_k = min(limit, z)
                for k in range(1, max_k + 1):
                    total += dp1[z - k][o]
                dp0[z][o] = (dp0[z][o] + total) % MOD
            # dp1[z][o]: last block is ones, length k (1..min(limit,o))
            if o > 0:
                total = 0
                max_k = min(limit, o)
                for k in range(1, max_k + 1):
                    total += dp0[z][o - k]
                dp1[z][o] = (dp1[z][o] + total) % MOD

    return (dp0[zero][one] + dp1[zero][one]) % MOD
