def maxSumOfSquares(nums, k):
    MOD = 10**9 + 7
    bits = 32
    cnt = [0] * bits
    for num in nums:
        for b in range(bits):
            if num & (1 << b):
                cnt[b] += 1

    result = 0
    for _ in range(k):
        val = 0
        for b in range(bits):
            if cnt[b] > 0:
                val |= (1 << b)
                cnt[b] -= 1
        result = (result + val * val) % MOD

    return result
