    def can_erase(i):
        has_letter = False
        for j in range(M):
            if A[i + j] != "#":
                if A[i + j] != T[j]:
                    return False
                has_letter = True
        return has_letter

    q = deque()

    for i in range(starts):
        if can_erase(i):
            q.append(i)

    erased = 0

    while q:
        i = q.popleft()

        if used[i]:
            continue
        if not can_erase(i):
            continue

        used[i] = True
        changed = []

        for j in range(M):
            pos = i + j
            if A[pos] != "#":
                A[pos] = "#"
                erased += 1
                changed.append(pos)

        for pos in changed:
            left = max(0, pos - M + 1)
            right = min(pos, N - M)
            for ni in range(left, right + 1):
                if not used[ni] and can_erase(ni):
                    q.append(ni)

    print("Yes" if erased == N else "No")

solve()

