    for _ in range(N):
        A = int(input_data[idx]); idx+=1
        B = int(input_data[idx]); idx+=1
        tiles.append((A,B))

    covered = [[False]*W for _ in range(H)]
    used = [False]*N

    def find_empty():
        for r in range(H):
            for c in range(W):
                if not covered[r][c]:
                    return r,c
        return None

    def can_place(r,c,a,b):
        if r+a>H or c+b>W:
            return False
        for i in range(r, r+a):
            for j in range(c, c+b):
                if covered[i][j]:
                    return False
        return True

    def place(r,c,a,b,val):
        for i in range(r, r+a):
            for j in range(c, c+b):
                covered[i][j] = val

    def dfs():
        pos = find_empty()
        if pos is None:
            return True
        r, c = pos
        for idx_t in range(N):
            if used[idx_t]:
                continue
            A, B = tiles[idx_t]
            orientations = set()
            orientations.add((A,B))
            orientations.add((B,A))
            for (a,b) in orientations:
                if can_place(r,c,a,b):
                    place(r,c,a,b,True)
                    used[idx_t] = True
                    if dfs():
                        return True
                    used[idx_t] = False
                    place(r,c,a,b,False)
        return False

    if dfs():
        print("Yes")
    else:
        print("No")

