from collections import deque

def minOperations(x: int, y: int) -> int:
    if x == y:
        return 0

    upper_bound = max(x, y) + 50
    visited = [False] * (upper_bound + 1)
    queue = deque([(x, 0)])
    visited[x] = True

    while queue:
        cur, steps = queue.popleft()

        if cur == y:
            return steps

        next_states = []
        if cur % 11 == 0:
            next_states.append(cur // 11)
        if cur % 5 == 0:
            next_states.append(cur // 5)
        next_states.append(cur - 1)
        next_states.append(cur + 1)

        for ns in next_states:
            if 0 <= ns <= upper_bound and not visited[ns]:
                visited[ns] = True
                queue.append((ns, steps + 1))

    return -1
