def smallestString(s: str, k: int) -> str:
    def cyclic_dist(a, b):
        d = abs(a - b)
        return min(d, 26 - d)

    t = []
    remaining = k
    for ch in s:
        c = ord(ch) - ord('a')
        cost_to_a = min(c, 26 - c)
        if remaining >= cost_to_a:
            t.append('a')
            remaining -= cost_to_a
        else:
            best_x = None
            for x in range(26):
                if cyclic_dist(c, x) <= remaining:
                    if best_x is None or x < best_x:
                        best_x = x
            t.append(chr(ord('a') + best_x))
            remaining = 0
    return "".join(t)
