                                t2 = r2 + k2 * M
                                t3 = r3 + k3 * M
                                if t1 != t2 and t2 != t3 and t1 != t3:
                                    mx = max(t1, t2, t3)
                                    if best is None or mx < best:
                                        best = mx

    if best is None:
